-- Quiz Questions data imported from CSV (with explanations)
INSERT INTO public.quiz_questions (question_text, choices, correct_choice_index, explanation) VALUES
('スナックメーカー「湖池屋」の「湖」はどんな湖のことを指しているでしょう？', '["諏訪湖", "琵琶湖", "十和田湖", "浜名湖"]'::jsonb, 0, ''),
('梶井基次郎の小説『桜の樹の下には』で、主人公が桜の樹の下に埋まっていると考えるのは何でしょう？', '["金", "刀", "自分", "屍体"]'::jsonb, 3, ''),
('長田高校マスコットキャラクターである、あすトラには、血の代わりに苅藻川の水が流れている。', '["正しい", "正しくない", "わからない", "血の代わりに星に至らむのぞみが流れている"]'::jsonb, 2, ''),
('QWERTY配列のキーボードで、右手人差し指のホームポジションは「J」ですが、左手人差し指のホームポジションは何でしょう？', '["S", "D", "F", "G"]'::jsonb, 2, ''),
('深夜アニメとして制作された続編『~MIRAI DAYS~』も人気を博した、朝比奈みらいとリコの不思議な出会いを描く『プリキュア』シリーズは何でしょう？', '["『ふたりはプリキュア』", "『名探偵プリキュア！』", "『魔法つかいプリキュア！』", "『HUGっと！プリキュア』"]'::jsonb, 2, ''),
('『機動戦士ガンダム』シリーズにおいて、「ν(ニュー)ガンダム」や「サザビー」といったモビルスーツが登場する作品は何でしょう？', '["『機動戦士ガンダム 閃光のハサウェイ』", "『機動戦士ガンダム 水星の魔女』", "『機動戦士ガンダム 逆襲のシャア』", "『機動戦士ガンダム GQuuuuuuX』"]'::jsonb, 2, ''),
('一般的に、カラーボールは犯人のどこに投げるのがよいとされているでしょう？', '["頭", "胴体", "足元", "明後日の方向"]'::jsonb, 2, ''),
('「見て見ぬふり」を言い表す英語の表現で「部屋の中にいる」と言われる動物は何でしょう？', '["ゾウ", "オオカミ", "ヘビ", "ライオン"]'::jsonb, 0, '「The elephant in the room」。全員が見えているはずなのに、触れると面倒なことになるのは分かりきっているのであえて誰も言及しないもののことだそうな。海外のことわざって面白いですよ。'),
('空気中では自然発火する恐れがあるため水に入れて保管する必要がある、 リンの同素体の一つといえば何でしょう？', '["赤リン", "青リン", "黄リン", "黒リン"]'::jsonb, 2, '高校生の皆さん、とりあえず「赤リン」と「黄リン」の2択には持ち込めましたよね？？？'),
('『君とアイドルプリキュア♪』の「響カイト」役や『キルアオ』の「古波鮫シン」役など声優としても活躍している、Snow Manのメンバーは誰でしょう？', '["岩本照", "ラウール", "阿部亮平", "佐久間大介"]'::jsonb, 3, 'Snow Manのピンクの人です。佐久間さんは芸能人枠とかでなく、オーディションとか受けて声優業をやってるらしいですね。キミプリの響カイト、めっちゃいいですよ。正直惚れました。'),
('数多の著名人に愛されたことから「カクテルの王様」の異名をとるカクテルは何でしょう？', '["ギムレット", "ジン", "マティーニ", "ソルティドッグ"]'::jsonb, 2, 'お酒はお好きですか？私は程々にしていますが、嫌いじゃないですよ。お酒は長田生の嗜みですからね。このマティーニはチャーチルやヘミングウェイといった人たちに愛されたそうな。'),
('「ジプシーの歌」「闘牛士の歌」「ハバネラ」といったアリアが歌われる、ビゼー作曲のオペラは何でしょう？', '["『愛の妙薬』", "『カルメン』", "『レ・ミゼラブル』", "『トゥーランドット』"]'::jsonb, 1, 'ぜひ聞いてみましょう。多分聞いたことある曲ですよ。'),
('「シャドーロールの怪物」の異名で親しまれた、 平成最初のクラシック三冠馬の名は何でしょう？', '["オルフェーブル", "シンボリルドルフ", "オグリキャップ", "ナリタブライアン"]'::jsonb, 3, '長田生ってどうして皆「競馬・麻雀・政治」に対して造詣が深いんですかね...。私はお馬さんはあんまり詳しくないですが、こんな問題があっても楽しいですよね。'),
('長田高校で活動している「長田高校クイズ研究会(通称NQL)」は皆さんご存知ですね。しかし長田高校に「クイズ部」はありません。では、NQLは名義上はどんな部活でしょう？', '["数学部", "科学部", "物理部", "天文部"]'::jsonb, 2, 'NQLの歴史自体は浅いらしいですが、その歴史を知る人間も消えつつあります。聞いた話によると、もとは有志団体だったのを物理部が受け入れたらしいです。それまで物理部は星を見ていたようで、数十年前の星空観察の記録が残っていたり。そんなNQLは今日の文化祭でも早押しクイズ体験を行っています。ぜひ来てね。'),
('ベートーベンの「歓喜の歌」に乗せて歌われる「抗えない 三大欲求 神のまにまに」というサビが印象的な、NTRをテーマにした雨良のボカロ曲は何でしょう？', '["『モニタリング』", "『いますぐ輪廻』", "『あいのうた』", "『バゥムクゥヘン・エンドロゥル』"]'::jsonb, 3, '「バームクーヘン・エンドロール」ってのは「仲の良い2人組の片割れが、物語の中で他の相手と結ばれウェディングケーキを食べ、残された方が一人で引き出物のバウムクーヘンを食べることになる結末」らしい。え、鬱。やっぱ純愛こそ正義なんですよ。'),
('持ち込まれたものは騙されて買った偽物であった、『竹取物語』で阿部右大臣が要求された難題は何でしょう？', '["蓬莱の玉の枝", "火鼠の皮衣", "燕の子安貝", "仏の石の鉢"]'::jsonb, 1, '車持皇子に要求された蓬莱の玉の枝はとーっても有名なので、あえてズラしてみました。竹取物語が嫌いな日本人はいないと思っていまして、創作でもこれをベースとした作品が結構ありますね。超かぐや姫とか東方永夜抄とか。竹取物語も教科書の知識でなく、教養として知っておきたいですね。'),
('ヘイムダルの吹くギャラルホルンによってこれの訪れが知らされる、北欧神話における「終末の日」は何でしょう？', '["ワルキューレ", "ドゥームズデイ", "アルマゲドン", "ラグナロク"]'::jsonb, 3, 'このラグナロク、結構終末で北欧神話の主神オーディンも死にます。'),
('人文・数理探究類型は別名なんと自称しているか', '["はちくみんず", "８組の民", "探究者", "実質某総〇理学"]'::jsonb, 0, '私自身もいつからこのように呼び始めたのかは知りません'),
('長田高校の最寄り駅である高速長田駅、地下鉄長田駅に、乗り換え無しで行くことができる駅として誤っているものを答えなさい。', '["西神中央駅", "明石駅", "王子公園駅", "谷上駅"]'::jsonb, 2, '西神中央駅は神戸市営地下鉄、明石駅は山陽電鉄で繋がっています。谷上駅は地下鉄と北神線をまたぎますが、乗りっぱなしで到着するため当てはまります。
王子公園駅は、どの路線でも三宮で神戸線に乗り換える必要があるため誤りです。'),
('長田高校の伝統(？)である周回走は女子が5周であるが、男子は何周か？', '["5", "6", "7", "8"]'::jsonb, 1, '男子は女子より1周多い6周を走っている'),
('体育で行われる「ロング走」は、何周走るでしょうか？', '["9周（3690m）", "10周（4100m）", "11周（4510m）", "12周（4920m）"]'::jsonb, 2, 'ロング走は2、3学期に1回くらいずつ行われます。周回走とは違って、気分の上がる曲がグラウンドで流されるので、周回走よりロングの方が好きな人のほうが多いかもしれません。男女で周数は同じなので、最後まで残ると、走り終わった沢山の人に応援されます…！(⁠ꏿ⁠﹏⁠ꏿ⁠;⁠)'),
('アニメ『NEEDY GIRL OVERDOSE』でしばしば取り入れられている、消費社会やデジタル文化を風刺するコア概念は何でしょう？', '["フルティガーエアロ", "ドリームコア", "ヴェイパーウェイヴ", "リミナルスペース"]'::jsonb, 2, 'まず何の話してるか分かりますか？コアっていいですよ。あなたに刺さる概念がきっとある。選択肢にある「フルティガーエアロ」「ヴェイパーウェイヴ」「ドリームコア」「リミナルスペース」は特に有名な奴らなので、調べてみたらなんか知ってるということもあるかなと。あ、あとニディガのアニメ面白いんで見ましょう。'),
('神撫会館が国の登録有形文化財に登録されたのは何年？', '["1994年", "2006年", "2010年", "2020年"]'::jsonb, 2, '2010年9月10日に登録されました'),
('長田高校の先生のお名前で実在しないのはどれ？', '["銀河", "力", "宙", "星雲"]'::jsonb, 3, '皆さんいい先生ばかりです。授業も面白いです。'),
('長田高校ではとても早い授業が行われているがそれを通称何と呼ばれている？？、', '["特急長田", "高速長田", "早しゅぎ長田", "早早長田"]'::jsonb, 1, '長田高校の最寄駅の一つである、神戸高速鉄道の「高速長田駅」が存在するのもあって、そう呼ばれているのです！！本当に授業スピードが早すぎる、、🥹（イガラッティー）'),
('長田高校の前身である「兵庫県立第三神戸中学校」が創立されたのは、西暦何年のことでしょうか？？', '["1918年", "1919年", "1920年", "1921年"]'::jsonb, 2, '長田高校の前身である「兵庫県立第三神戸中学校」が創立されたのは1920年で、今年で創立106周年を迎えます！！（イガラッティー）'),
('長田高校の校歌において、一番の冒頭で歌われる山、およびその土地の美称は何でしょうか。', '["駒ヶ林（こまがばやし）", "摩耶（まや）", "神撫（かんなで）", "雄鷹（おたか）"]'::jsonb, 2, '校歌の冒頭「神撫の山の松風に」と歌われる通り、高取山の古称や学校周辺の地を指す言葉として深く根付いています。'),
('長田高校は、戦後の学制改革において「兵庫県立第三神戸中学校」から現在の校名になりましたが、その際にある女学校と統合されました。その学校名は何でしょうか。', '["兵庫県立第四神戸高等女学校", "兵庫県立第一神戸高等女学校", "長田女子商業学校", "神戸市立第一女学校"]'::jsonb, 0, '1948年の学制改革により、第三神戸中学校と第四神戸高等女学校が統合され、現在の長田高校が誕生したぜ！（イガラッティー）'),
('長田高校とは', '["夢と希望と青春", "🫨"]'::jsonb, 0, '長田高校での生活、それはまさに夢と希望と青春である。（イガラッティー）'),
('ゲーム『学園アイドルマスター』において、『自己肯定感爆上げ↑↑しゅきしゅきソング』や『世界一可愛い私』を歌うアイドルは誰でしょう？', '["花海咲季", "姫崎莉波", "倉本千奈", "藤田ことね"]'::jsonb, 3, '学マスはいいぞおじさん「学マスはいいぞ」'),
('メガネの中でも、レンズが丸みのある逆さ台形のような形になっているもののことを特に何と言うでしょう？', '["ボストン", "メルボルン", "ウェリントン", "マンハッタン"]'::jsonb, 2, 'ウェリントンメガネ、いいですよね。私はこれを使っています(特定材料)。スクエアとは違ってもうちょっと優しい印象が出るといいますか。'),
('「ナスを食べよう♪」「FANのシンプル暴力60分」といったゴミ企画を考案し却下されている、奇抜なゴーグルが特徴の「バキ童ch」のスタッフは誰でしょう？', '["山田ボールペン", "もののけ", "金子", "馬肉かなめ"]'::jsonb, 3, 'ちなみに「FANのシンプル暴力60分」はそれに似たようなことが行われたそうな。'),
('YouTube版のMVは作者の誤操作で一度削除されてしまった、「ドミニカの大砲」と称される野球選手をテーマにした山本のボカロ曲は何でしょう？', '["デロスサントス", "サンタナ", "フェルナンデス", "ロハスjr."]'::jsonb, 0, '歌詞に登場する「掘りごたつ」「イタリアン」「海の見える店」の三条件を満たす店は実在します。シーサイドカプリみたいな店だったはず。'),
('バンダイが販売する一般的な「ガンプラ」において、以下のうち最も縮尺が大きい(実寸大に近い)のはどれ？', '["EG(エントリーグレード)", "MG(マスターグレード)", "RG(リアルグレード)", "HG(ハイグレード)"]'::jsonb, 1, 'マスターグレードは基本的に1/100スケール、ほかは全て1/144ですね。ちなみにPG(パーフェクトグレード)ってのは1/60でデカい。ただし高い。最新のPGはνガンダムなんですが、6万くらいする。誰か買って。'),
('その難関大学群は「SKY」と言われる国はどこでしょう？', '["インド", "オーストラリア", "韓国", "オランダ"]'::jsonb, 2, '「ソウル大学」「高麗大学」「延世(ヨンセ)大学」の頭文字を取って「SKY」です。韓国人の人生は「ソウル大学に行く」か「チキン屋になる」か「自殺するか」しかないってジョークが有名ですね。最近は時代に合わせてチキン屋じゃなくてVtuberになるらしいっすよ。'),
('長田高校は今年で創立何年？', '["106", "107", "108", "109"]'::jsonb, 0, '2020年に100周年を迎えた'),
('長田高校で「ナビしない」と言うと、何になる？', '["いやするでしょ", "旅したい", "梨見ない", "風にーなりーたいー"]'::jsonb, 1, '「な」が「た」高校だから
なびしない→たびしたい'),
('この問題を解いて下さい。賢い君たちなら分かるはず。', '["40°", "45°", "60°", "65°"]'::jsonb, 1, 'まあ、参考を見て下さい。問題のためにもう一個写真載せたいです。'),
('長田高校から1番遠い高校は？？', '["兵庫高校", "彩星工科", "夢野台", "御影"]'::jsonb, 3, '御影高校以外は、少し歩けばすぐ着きます！（イガラッティー）'),
('入学式での隣の人との席の距離はどれくらいでしょうか。', '["ゼロ距離", "ミリ距離", "センチ距離", "メートル距離"]'::jsonb, 0, '初日から隣の人との距離は近くなるから、不安も恐怖も吹っ飛びます😁'),
('初代校長、近藤英也の読みを答えよ', '["こんとうひてや", "こんどうひて\"や", "こんどうえいや！", "こんどうひでや"]'::jsonb, 3, '選択肢2を選んだ人は、注意力が足りません。'),
('次の中で本当に起こった出来事はなに？', '["先生が昼休みに平然と授業を開始する", "京都遠足に先生が着物にお歯黒をしてくる", "グラウンドから火が上がる", "講演会にアメリカのラッパーが来る"]'::jsonb, 0, '長田にはたくさん非常勤講師がいます。
彼らはユニークな授業をしてくれますが、皆お年を召されてるので、多少の失敗は見逃してあげましょう。
ちなみに、日本人のラッパーは来ました。'),
('長田高校公式グッズのうち、正しい物はどれか。', '["リカちゃん人形", "どらえもん", "忍者ハットリくん", "ゲゲゲの鬼太郎"]'::jsonb, 0, '創立100周年記念として、神撫会によって製作されたよ。筆者は姉に譲り受けて今でも時々学校に持ってきてるよ。公式グッズだからベテランの先生に聞いてみよう！！
作問:長田に恋して12年目'),
('長田高校の旧名は次のうちどれ？', '["兵庫県立第三神戸中学校", "神撫ヶ丘高校", "兵庫県高等教育第四支部", "池田谷中学校"]'::jsonb, 0, 'ちなみに選択肢2の神撫ヶ丘高校は改名する際に候補に挙がってたと思います。こっちのがかっこいいやんけ。詳しくは開門章参照です。
作問:5歳の頃に長田に惚れました。'),
('昔の文化祭でほんとにあったのは次のうちどっち？', '["各部活の出し物", "一般祭が土日の2日間"]'::jsonb, 0, '昔は剣道部とかが焼きそば焼いてたはずです。
日程が総体とかと被っちゃう部活多くて寂しいよね。
作問:文化祭に惚れて受験した人。'),
('長田生のよくないところは？', '["スカしすぎるところ", "逆張っちゃうところ", "ガリ勉すぎるところ", "そんなとこも含めて愛おしい♥"]'::jsonb, 3, '高校生だからね。多感な時期だし、そういうのも沢山あります。でもそういうとこが可愛いんだなぁ。
作問:長田の信者'),
('長田高校にある部活・特別委員会の数を答えよ(生徒会・文スタ・体スタ除く)', '["39", "50", "34", "47"]'::jsonb, 0, '運動部21   文化部15     委員会3'),
('周回走が始まったのは約何年前？', '["10年前", "20年前", "50年前", "100年前（創立時）"]'::jsonb, 2, '学生運動の影響を浴びて授業を行うのが難しくなった時代に、せめて走らせてくれ、と生徒が頼んだことで始まった（らしい）。この話を聞き、創立当初からの伝統じゃないのかよ！と若干やる気をなくす者が発生。'),
('コンピューター室のエアコンについて正しいものを選べ', '["エアコンはない", "エアコンはあるが、職員室で管理されている", "コンピューター室で自由にエアコンを調整できる"]'::jsonb, 2, 'コンピューター室のエアコンは情報の正井先生が牛耳っています。夏は涼しくて冬は暖かいです。'),
('ンバヂの楽曲『好きな惣菜発表ドラゴン』で唯一2回登場する惣菜は何でしょう？', '["からあげ", "ハンバーグ", "とんかつ", "肉を甘辛く炒めたやつ"]'::jsonb, 2, '正式名称が分からない惣菜もすきすきだいすき。'),
('そのへっぽこぶりから、ファンからは｢小林｣と謎の名字呼びで愛されている、『名探偵プリキュア！』に登場する桃色のプリキュアは誰でしょう？', '["キュアアンサー", "キュアミスティック", "キュアエクレール", "キュアアルカナ･シャドウ"]'::jsonb, 1, 'キュアミスティック、本名は｢小林みくる｣。今現在出てるプリキュアのなかでは一番表情豊かで反応も可愛くて好きです。おばけを怖がる小林いいぞ。'),
('長田高校で実際に食べられる食堂のメニューはなんでしょう？', '["牛丼", "ハンバーグ", "そば", "唐揚げ丼"]'::jsonb, 3, '唐揚げ丼は日替わりメニューです。おいしいのでぜひ食べてみてほしいです！オススメです！'),
('長田にいるライオンは何色でしょう？', '["赤", "オレンジ", "うすめのオレンジ", "金"]'::jsonb, 3, '知らなかった人は是非探してみてね'),
('長田高校の開校記念日はいつでしょう？', '["1920年", "1921年", "1922年"]'::jsonb, 1, '毎年、創立記念日（4/16）には校長先生による全校生徒への講話があります。');
